package com.minecraftmoba.plugin;
import org.bukkit.*;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.*;
import org.bukkit.entity.minecart.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.event.vehicle.*;
import org.bukkit.inventory.*;
import org.bukkit.util.Vector;
import java.util.*;
/** Actual driven vehicles; independent temporary opportunities, parking and physical collisions. */
final class ChauffeurState implements Listener {
 static final class Ride {final Player owner;final Vehicle vehicle;final String kind;final Inventory cargo;final int until;String branch;int boostUntil,unmannedUntil;Vector momentum=new Vector();final Set<UUID> touching=new HashSet<>();Material fuel=Material.COAL;
  Ride(Player p,Vehicle v,String kind,String branch,int until){owner=p;vehicle=v;this.kind=kind;this.branch=branch;this.until=until;cargo=kind.equals("boat")?Bukkit.createInventory(null,27,"Cargo Boat"):null;}}
 private record Race(Location from,Location parking,int until,Set<UUID> marked){}
 private final MobaPlugin plugin;private final ConfigurationSection cfg;private int clock;private final Map<UUID,Ride> rides=new HashMap<>();private final Map<UUID,Location> parking=new HashMap<>();private final Map<UUID,Race> races=new HashMap<>();private final Map<UUID,Material> fuels=new HashMap<>();private final Map<UUID,Double> originalSpeed=new HashMap<>();
 ChauffeurState(MobaPlugin p){plugin=p;cfg=p.getConfig().getConfigurationSection("chauffeur");}
 private boolean has(Player p){return KitSupport.has(plugin,p,"chauffeur")&&plugin.passives().has(p,"parking_spot");}
 boolean summon(Player p,String kind,String branch){Ride old=rides.values().stream().filter(r->r.owner.equals(p)&&r.kind.equals(kind)).findFirst().orElse(null);if(old!=null)remove(old);Location at=KitSupport.safe(p.getLocation().clone().add(p.getLocation().getDirection().setY(0).multiply(2)),2);if(at==null)return false;Vehicle vehicle=kind.equals("boat")?(Vehicle)p.getWorld().spawnEntity(at,EntityType.OAK_BOAT):p.getWorld().spawn(at,RideableMinecart.class);vehicle.setPersistent(false);OwnedEntities.tag(vehicle,p);Ride ride=new Ride(p,vehicle,kind,branch,clock+cfg.getInt("summonTicks"));rides.put(vehicle.getUniqueId(),ride);vehicle.addPassenger(p);return true;}
 boolean race(Player p){Location spot=parking.get(p.getUniqueId());if(spot==null){var d=plugin.data(p);if(d!=null&&d.classState.containsKey("parking.world")){World w=Bukkit.getWorld(UUID.fromString(d.classState.get("parking.world")));if(w!=null)spot=new Location(w,Double.parseDouble(d.classState.get("parking.x")),Double.parseDouble(d.classState.get("parking.y")),Double.parseDouble(d.classState.get("parking.z")));}}if(spot==null||spot.getWorld()!=p.getWorld())return false;Vector line=spot.toVector().subtract(p.getLocation().toVector());if(line.lengthSquared()<1)return false;Set<UUID> marked=new HashSet<>();for(var enemy:KitSupport.enemies(p,p.getLocation(),Math.min(cfg.getDouble("raceRange"),line.length()+cfg.getDouble("raceCorridor")))){Vector offset=enemy.getLocation().toVector().subtract(p.getLocation().toVector());double along=Math.max(0,Math.min(1,offset.dot(line)/line.lengthSquared()));if(offset.subtract(line.clone().multiply(along)).lengthSquared()<=cfg.getDouble("raceCorridor")*cfg.getDouble("raceCorridor")){marked.add(enemy.getUniqueId());plugin.kitGlow().acquire(enemy,"race-mark:"+p.getUniqueId());}}plugin.kitGlow().acquire(p,"racing");races.put(p.getUniqueId(),new Race(p.getLocation(),spot,clock+cfg.getInt("raceTicks"),marked));return true;}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void exit(VehicleExitEvent e){if(!(e.getExited() instanceof Player p)||!has(p))return;Ride ride=rides.get(e.getVehicle().getUniqueId());if(ride!=null&&ride.owner.equals(p)){Location at=p.getLocation();parking.put(p.getUniqueId(),at.clone());var d=plugin.data(p);d.classState.put("parking.world",at.getWorld().getUID().toString());d.classState.put("parking.x",Double.toString(at.getX()));d.classState.put("parking.y",Double.toString(at.getY()));d.classState.put("parking.z",Double.toString(at.getZ()));}
  if(e.getVehicle() instanceof Minecart&&KitSupport.branch(plugin,p,"muscle_cart").equals("tactical_dismount")){if(ride==null){ride=new Ride(p,e.getVehicle(),"ordinary_cart","tactical_dismount",clock+cfg.getInt("unmannedTicks"));rides.put(e.getVehicle().getUniqueId(),ride);}ride.momentum=e.getVehicle().getVelocity();ride.unmannedUntil=clock+cfg.getInt("unmannedTicks");}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void enter(VehicleEnterEvent e){if(e.getEntered() instanceof Player p&&has(p)){Ride ride=rides.get(e.getVehicle().getUniqueId());Location at=parking.get(p.getUniqueId());if(ride!=null&&at!=null&&at.getWorld()==p.getWorld()&&at.distanceSquared(p.getLocation())<=cfg.getDouble("parkingRadius")*cfg.getDouble("parkingRadius"))ride.boostUntil=clock+cfg.getInt("parkingBoostTicks");}}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true) public void interact(PlayerInteractEntityEvent e){Player p=e.getPlayer();if(!has(p)||e.getHand()!=EquipmentSlot.HAND||plugin.inputs().active(p))return;Ride ride=rides.get(e.getRightClicked().getUniqueId());if(ride!=null&&ride.cargo!=null&&p.isSneaking()){e.setCancelled(true);p.openInventory(ride.cargo);return;}if(e.getRightClicked() instanceof PoweredMinecart&&KitSupport.branch(plugin,p,"muscle_cart").equals("diesel_engine")){Material material=p.getInventory().getItemInMainHand().getType();if(material==Material.COAL||material==Material.CHARCOAL){fuels.put(e.getRightClicked().getUniqueId(),material);return;}}if(e.getRightClicked() instanceof Minecart cart&&!p.isSneaking()&&cart.getPassengers().isEmpty()){e.setCancelled(true);cart.addPassenger(p);}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void damage(VehicleDestroyEvent e){Ride r=rides.get(e.getVehicle().getUniqueId());if(r!=null){spill(r);rides.remove(r.vehicle.getUniqueId());}}
 private void spill(Ride r){if(r.cargo!=null){for(var item:r.cargo.getContents())if(item!=null&&!item.isEmpty())r.vehicle.getWorld().dropItemNaturally(r.vehicle.getLocation(),item.clone());r.cargo.clear();}}
 private void remove(Ride r){if(r.cargo!=null)for(var p:List.copyOf(r.cargo.getViewers()))p.closeInventory();spill(r);if(!r.kind.equals("ordinary_cart"))r.vehicle.remove();rides.remove(r.vehicle.getUniqueId());}
 void tick(){clock++;if(plugin.inputs()==null)return;
  for(var p:Bukkit.getOnlinePlayers())if(has(p)&&p.getVehicle() instanceof Vehicle v&&!rides.containsKey(v.getUniqueId())){if(v instanceof Minecart cart){originalSpeed.putIfAbsent(cart.getUniqueId(),cart.getMaxSpeed());cart.setMaxSpeed(cfg.getDouble("railSpeed"));if(v.getLocation().getBlock().getType().name().endsWith("RAIL")){Vector direction=v.getVelocity().lengthSquared()>.001?v.getVelocity().clone().normalize():p.getLocation().getDirection().setY(0).normalize();v.setVelocity(direction.multiply(cfg.getDouble("railSpeed")));}if(v instanceof PoweredMinecart powered&&powered.getFuel()>0&&KitSupport.branch(plugin,p,"muscle_cart").equals("diesel_engine"))v.setVelocity(v.getVelocity().multiply(fuels.getOrDefault(v.getUniqueId(),Material.COAL)==Material.CHARCOAL?cfg.getDouble("charcoalBoost"):cfg.getDouble("coalBoost")));if(!(v instanceof RideableMinecart)&&v.getPassengers().isEmpty())v.addPassenger(p);ordinaryCollision(p,v);}else if(v instanceof Boat&&!v.isInWater()){Vector velocity=v.getVelocity();double cap=cfg.getDouble("boatSpeed");if(velocity.lengthSquared()>cap*cap)velocity.normalize().multiply(cap);else velocity.multiply(cfg.getDouble("landBoatBoost"));v.setVelocity(velocity);}
 Race race=races.get(p.getUniqueId());if(race!=null&&clock<race.until&&race.parking.getWorld()==v.getWorld()){Vector toward=race.parking.toVector().subtract(v.getLocation().toVector());if(toward.lengthSquared()>.01&&v.getVelocity().dot(toward)>0)v.setVelocity(v.getVelocity().multiply(cfg.getDouble("raceSpeed")).normalize().multiply(cfg.getDouble("railSpeed")*cfg.getDouble("raceSpeed")));for(var enemy:KitSupport.enemies(p,v.getLocation(),cfg.getDouble("collisionRadius")))if(race.marked.remove(enemy.getUniqueId())){plugin.kitGlow().release(enemy,"race-mark:"+p.getUniqueId());v.setVelocity(v.getVelocity().multiply(cfg.getDouble("markedAcceleration")));}}}
  for(var entry:List.copyOf(originalSpeed.entrySet())){Entity entity=Bukkit.getEntity(entry.getKey());if(!(entity instanceof Minecart cart)||cart.getPassengers().stream().noneMatch(e->e instanceof Player p&&has(p))){if(entity instanceof Minecart cart)cart.setMaxSpeed(entry.getValue());originalSpeed.remove(entry.getKey());}}
  for(var r:List.copyOf(rides.values())){if(!r.vehicle.isValid()||!has(r.owner)){remove(r);continue;}if(clock>=r.until){if(r.unmannedUntil>0&&r.vehicle instanceof ExplosiveMinecart cart)cart.explode();remove(r);continue;}Player driver=r.vehicle.getPassengers().stream().filter(e->e instanceof Player p&&has(p)).map(e->(Player)e).findFirst().orElse(null);boolean unmanned=clock<r.unmannedUntil;
   if(driver!=null&&!plugin.stun().movementRefused(driver)){Vector direction=driver.getLocation().getDirection().setY(0).normalize();boolean forward=driver.getCurrentInput().isForward();double speed=cfg.getDouble(r.kind.equals("boat")?"boatSpeed":"cartSpeed");if(clock<r.boostUntil)speed*=cfg.getDouble("parkingSpeed");if(r.branch.equals("freight_engine")&&r.cargo!=null&&Arrays.stream(r.cargo.getContents()).allMatch(item->item!=null&&item.getAmount()>=item.getMaxStackSize()))speed*=cfg.getDouble("freightSpeed");Race race=races.get(driver.getUniqueId());if(race!=null&&race.until>clock&&race.parking.getWorld()==r.vehicle.getWorld()&&direction.dot(race.parking.toVector().subtract(r.vehicle.getLocation().toVector()).normalize())>.4)speed*=cfg.getDouble("raceSpeed");if(r.branch.equals("jetski")&&r.vehicle.getLocation().getBlock().getType()==Material.BUBBLE_COLUMN)r.momentum.setY(r.momentum.getY()+cfg.getDouble("bubbleAcceleration"));double turn=r.kind.equals("boat")?cfg.getDouble("boatTurn"):cfg.getDouble("cartTurn");Vector intended=forward?direction.multiply(speed):new Vector();r.momentum.multiply(1-turn).add(intended.multiply(turn));r.vehicle.setVelocity(r.momentum.clone());r.vehicle.setRotation(driver.getYaw(),0);
   }else if(unmanned)r.vehicle.setVelocity(r.momentum.clone());
   Set<UUID> touching=new HashSet<>();for(var enemy:KitSupport.enemies(r.owner,r.vehicle.getLocation(),cfg.getDouble("collisionRadius"))){touching.add(enemy.getUniqueId());if(r.touching.contains(enemy.getUniqueId())||r.vehicle.getVelocity().lengthSquared()<.015)continue;Vector offset=enemy.getLocation().toVector().subtract(r.vehicle.getLocation().toVector()).setY(0);boolean front=offset.lengthSquared()>.01&&offset.normalize().dot(r.vehicle.getLocation().getDirection().setY(0).normalize())>.5;if(!r.kind.equals("boat")||r.branch.equals("front_propeller")&&front){double damage=unmanned?cfg.getDouble("unmannedDamage"):r.kind.equals("boat")?cfg.getDouble("propellerDamage"):0;if(damage>0)AbilityDamage.deal(enemy,damage,r.owner);KitSupport.push(plugin,enemy,r.vehicle.getVelocity().clone().normalize().multiply(cfg.getDouble("collisionPush")).setY(.3));}Race race=races.get(r.owner.getUniqueId());if(race!=null&&race.marked.contains(enemy.getUniqueId())){r.momentum.multiply(cfg.getDouble("markedAcceleration"));race.marked.remove(enemy.getUniqueId());plugin.kitGlow().release(enemy,"race-mark:"+r.owner.getUniqueId());}}
   r.touching.clear();r.touching.addAll(touching);if(r.unmannedUntil>0&&clock>=r.unmannedUntil){if(r.vehicle instanceof ExplosiveMinecart cart)cart.explode();r.unmannedUntil=0;if(r.kind.equals("ordinary_cart"))rides.remove(r.vehicle.getUniqueId());}
  }
  if(clock%5==0)for(var race:races.values()){Vector span=race.parking.toVector().subtract(race.from.toVector());int steps=Math.min(128,(int)Math.ceil(span.length()));if(steps>0)for(int i=0;i<=steps;i++)race.from.getWorld().spawnParticle(Particle.END_ROD,race.from.clone().add(span.clone().multiply(i/(double)steps)).add(0,.2,0),1);}
  for(var entry:List.copyOf(races.entrySet()))if(clock>=entry.getValue().until){for(UUID id:entry.getValue().marked){Entity e=Bukkit.getEntity(id);if(e!=null)plugin.kitGlow().release(e,"race-mark:"+entry.getKey());}Player owner=Bukkit.getPlayer(entry.getKey());if(owner!=null)plugin.kitGlow().release(owner,"racing");races.remove(entry.getKey());}
 }
 private void ordinaryCollision(Player p,Vehicle v){for(var enemy:KitSupport.enemies(p,v.getLocation(),cfg.getDouble("collisionRadius"))){if(v.getVelocity().lengthSquared()<.04)continue;double y=v instanceof HopperMinecart&&KitSupport.branch(plugin,p,"muscle_cart").equals("pop_the_hopper")?cfg.getDouble("hopperLaunch"):.3;KitSupport.push(plugin,enemy,v.getVelocity().clone().normalize().multiply(cfg.getDouble("collisionPush")).setY(y));}}
 void forget(Player p){for(var r:List.copyOf(rides.values()))if(r.owner.equals(p))remove(r);Race race=races.remove(p.getUniqueId());if(race!=null)for(UUID id:race.marked){Entity e=Bukkit.getEntity(id);if(e!=null)plugin.kitGlow().release(e,"race-mark:"+p.getUniqueId());}plugin.kitGlow().release(p,"racing");parking.remove(p.getUniqueId());}
 void close(){for(var r:List.copyOf(rides.values()))remove(r);for(UUID owner:List.copyOf(races.keySet())){Player p=Bukkit.getPlayer(owner);if(p!=null)forget(p);}races.clear();for(var entry:originalSpeed.entrySet()){Entity entity=Bukkit.getEntity(entry.getKey());if(entity instanceof Minecart cart)cart.setMaxSpeed(entry.getValue());}originalSpeed.clear();fuels.clear();}
}
